CREATE OR REPLACE FUNCTION public.deposit_payout_verified(_inquiry uuid, _cents bigint) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _cents>0 AND COALESCE(sum(d.amount_cents),0)>=_cents FROM public.deposit_refunds d JOIN public.offer_payment_links l ON l.id=d.link_id JOIN public.stripe_refund_receipts p ON p.refund_id=d.stripe_refund_id AND p.payment_intent=l.payment_intent_id AND p.amount_cents=d.amount_cents AND p.livemode=l.livemode WHERE l.inquiry_table='rental_inquiries' AND l.inquiry_id=_inquiry AND d.status='succeeded' AND p.status='succeeded' AND p.currency='eur' $$;
REVOKE ALL ON FUNCTION public.deposit_payout_verified(uuid,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.deposit_payout_verified(uuid,bigint) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.guard_deposit_settlement_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Kautionsabrechnungen sind unveränderlich (GoBD) – Korrektur nur per Gutschrift'; END IF; IF (to_jsonb(NEW)-'payout_status'-'payout_date') IS DISTINCT FROM (to_jsonb(OLD)-'payout_status'-'payout_date') THEN RAISE EXCEPTION 'Kautionsabrechnungen sind unveränderlich (GoBD) – Korrektur nur per Gutschrift'; END IF; IF NEW.payout_method='stripe' AND NEW.payout_status='paid' AND NOT public.deposit_payout_verified(NEW.rental_inquiry_id,round(NEW.balance*100)::bigint) THEN RAISE EXCEPTION 'Stripe-Erstattung ist nicht durch erfolgreiche Zahlungsbelege bestätigt'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.mark_deposit_payout_done(_settlement_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.deposit_settlements; BEGIN IF NOT public.can_edit_operations(auth.uid()) THEN RAISE EXCEPTION 'Keine Berechtigung für Kautionserstattungen' USING ERRCODE='42501'; END IF; SELECT * INTO s FROM public.deposit_settlements WHERE id=_settlement_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Kautionsabrechnung nicht gefunden'; END IF; IF s.payout_method='stripe' AND NOT public.deposit_payout_verified(s.rental_inquiry_id,round(s.balance*100)::bigint) THEN RAISE EXCEPTION 'Stripe-Erstattung ist nicht durch erfolgreiche Zahlungsbelege bestätigt'; END IF; UPDATE public.deposit_settlements SET payout_status='paid',payout_date=current_date WHERE id=s.id AND payout_status='pending'; END $$;
REVOKE ALL ON FUNCTION public.mark_deposit_payout_done(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.mark_deposit_payout_done(uuid) TO authenticated;